"""Import real local database to Railway. Run: python import_db.py"""
import base64, sqlite3, os

DB_B64 = """"""

def import_db():
    sql = base64.b64decode(DB_B64.strip()).decode("utf-8")
    db_path = "./app.db"
    if os.path.exists(db_path):
        os.remove(db_path)
        print("Removed old database")
    conn = sqlite3.connect(db_path)
    conn.executescript(sql)
    conn.close()
    print(f"Database imported to {db_path}")
    c = sqlite3.connect(db_path)
    users = c.execute("SELECT COUNT(*) FROM users").fetchone()[0]
    lessons = c.execute("SELECT COUNT(*) FROM lessons").fetchone()[0]
    subjects = c.execute("SELECT COUNT(*) FROM subjects").fetchone()[0]
    enrolls = c.execute("SELECT COUNT(*) FROM lesson_enrollments").fetchone()[0]
    print(f"Users: {users}, Subjects: {subjects}, Lessons: {lessons}, Enrollments: {enrolls}")
    c.close()

if __name__ == "__main__":
    import_db()
